-- M1.0 schema: Access, Settings and Platform tables (docs/architecture/data-model.md).
-- Conventions: UUID PKs generated by the app, branch_id on business tables, timestamptz (UTC),
-- version for optimistic locking, enums as varchar + CHECK, money numeric(12,2), rates numeric(5,2).

CREATE TABLE branch (
    id          uuid PRIMARY KEY,
    name        varchar(100) NOT NULL,
    created_at  timestamptz  NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------- Access
CREATE TABLE permission (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    code        varchar(64)  NOT NULL UNIQUE,
    description varchar(200) NOT NULL,
    module      varchar(20)  NOT NULL CHECK (module IN ('ADMIN','ORDERS','BILLING','DISCOUNTS','KITCHEN','SHIFTS','REPORTS')),
    sort_order  int          NOT NULL
);

CREATE TABLE role (
    id          uuid PRIMARY KEY,
    branch_id   uuid         NOT NULL REFERENCES branch (id),
    name        varchar(50)  NOT NULL,
    description varchar(200),
    system      boolean      NOT NULL DEFAULT false,
    -- Stable key of a seeded role (names are fixed too, but code never depends on display text).
    system_code varchar(20)  UNIQUE CHECK (system_code IN ('OWNER','MANAGER','CASHIER','RECEPTIONIST','KITCHEN','RIDER','INVENTORY','HR')),
    version     int          NOT NULL DEFAULT 0,
    created_at  timestamptz  NOT NULL DEFAULT now(),
    updated_at  timestamptz  NOT NULL DEFAULT now(),
    created_by  uuid,
    updated_by  uuid,
    CHECK (system = (system_code IS NOT NULL))
);
CREATE UNIQUE INDEX ux_role_branch_name ON role (branch_id, lower(name));

CREATE TABLE role_permission (
    role_id       uuid NOT NULL REFERENCES role (id) ON DELETE CASCADE,
    permission_id uuid NOT NULL REFERENCES permission (id),
    PRIMARY KEY (role_id, permission_id)
);

CREATE TABLE app_user (
    id                   uuid PRIMARY KEY,
    branch_id            uuid         NOT NULL REFERENCES branch (id),
    username             varchar(32)  NOT NULL,
    password_hash        varchar(100) NOT NULL,
    pin_hash             varchar(100),
    full_name            varchar(100) NOT NULL,
    phone                varchar(20),
    active               boolean      NOT NULL DEFAULT true,
    failed_attempts      int          NOT NULL DEFAULT 0,
    locked_until         timestamptz,
    pin_failed_attempts  int          NOT NULL DEFAULT 0,
    pin_locked_until     timestamptz,
    last_login_at        timestamptz,
    employee_id          uuid,               -- Phase 5
    version              int          NOT NULL DEFAULT 0,
    created_at           timestamptz  NOT NULL DEFAULT now(),
    updated_at           timestamptz  NOT NULL DEFAULT now(),
    created_by           uuid,
    updated_by           uuid
);
CREATE UNIQUE INDEX ux_app_user_username ON app_user (lower(username));

CREATE TABLE user_role (
    user_id uuid NOT NULL REFERENCES app_user (id),
    role_id uuid NOT NULL REFERENCES role (id),   -- no cascade: a role in use cannot be deleted
    PRIMARY KEY (user_id, role_id)
);
CREATE INDEX ix_user_role_role ON user_role (role_id);

CREATE TABLE terminal (
    id                 uuid PRIMARY KEY,
    branch_id          uuid        NOT NULL REFERENCES branch (id),
    name               varchar(50) NOT NULL,
    type               varchar(20) NOT NULL CHECK (type IN ('CASHIER_POS','RECEPTION_POS','KITCHEN','ADMIN','DISPLAY')),
    kitchen_station_id uuid,        -- FK added in M1.1 with kitchen_station
    ordering_point_id  uuid,        -- FK added in M1.1 with ordering_point
    device_token_hash  varchar(64) NOT NULL UNIQUE,
    active             boolean     NOT NULL DEFAULT true,
    last_login_at      timestamptz,
    version            int         NOT NULL DEFAULT 0,
    created_at         timestamptz NOT NULL DEFAULT now(),
    updated_at         timestamptz NOT NULL DEFAULT now(),
    created_by         uuid,
    updated_by         uuid,
    CHECK ((type = 'KITCHEN') = (kitchen_station_id IS NOT NULL))
);
-- Names are unique among active terminals, so a re-registered device can reuse its old name.
CREATE UNIQUE INDEX ux_terminal_branch_name_active ON terminal (branch_id, lower(name)) WHERE active;

CREATE TABLE refresh_token (
    id          uuid PRIMARY KEY,
    user_id     uuid        NOT NULL REFERENCES app_user (id),
    terminal_id uuid        NOT NULL REFERENCES terminal (id),
    token_hash  varchar(64) NOT NULL UNIQUE,
    issued_at   timestamptz NOT NULL,
    expires_at  timestamptz NOT NULL,
    revoked_at  timestamptz,
    replaced_by uuid
);
CREATE INDEX ix_refresh_token_user_terminal ON refresh_token (user_id, terminal_id) WHERE revoked_at IS NULL;
CREATE INDEX ix_refresh_token_terminal ON refresh_token (terminal_id) WHERE revoked_at IS NULL;

-- ---------------------------------------------------------------- Settings
CREATE TABLE setting (
    id         uuid PRIMARY KEY,
    branch_id  uuid        NOT NULL REFERENCES branch (id),
    key        varchar(50) NOT NULL,
    value      jsonb       NOT NULL,
    version    int         NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_by uuid,
    UNIQUE (branch_id, key)
);

CREATE TABLE service_charge_rule (
    id         uuid PRIMARY KEY,
    branch_id  uuid         NOT NULL REFERENCES branch (id),
    order_type varchar(20)  NOT NULL CHECK (order_type IN ('DINE_IN','TAKEAWAY','DELIVERY')),
    rate       numeric(5,2) NOT NULL CHECK (rate >= 0 AND rate <= 100),
    version    int          NOT NULL DEFAULT 0,
    created_at timestamptz  NOT NULL DEFAULT now(),
    updated_at timestamptz  NOT NULL DEFAULT now(),
    created_by uuid,
    updated_by uuid,
    UNIQUE (branch_id, order_type)
);

-- Used from M1.2 / M1.4; created now as part of the Settings group in data-model.md.
CREATE TABLE delivery_area (
    id         uuid PRIMARY KEY,
    branch_id  uuid          NOT NULL REFERENCES branch (id),
    name       varchar(100)  NOT NULL,
    fee        numeric(12,2) NOT NULL CHECK (fee >= 0),
    active     boolean       NOT NULL DEFAULT true,
    version    int           NOT NULL DEFAULT 0,
    created_at timestamptz   NOT NULL DEFAULT now(),
    updated_at timestamptz   NOT NULL DEFAULT now(),
    created_by uuid,
    updated_by uuid
);

CREATE TABLE reason (
    id         uuid PRIMARY KEY,
    branch_id  uuid         NOT NULL REFERENCES branch (id),
    category   varchar(20)  NOT NULL CHECK (category IN ('CANCEL','VOID','REFUND','PETTY_CASH','DISCOUNT_OTHER')),
    text       varchar(200) NOT NULL,
    active     boolean      NOT NULL DEFAULT true,
    version    int          NOT NULL DEFAULT 0,
    created_at timestamptz  NOT NULL DEFAULT now(),
    updated_at timestamptz  NOT NULL DEFAULT now(),
    created_by uuid,
    updated_by uuid
);

CREATE TABLE discount_rule (
    id                      uuid PRIMARY KEY,
    branch_id               uuid          NOT NULL REFERENCES branch (id),
    type                    varchar(20)   NOT NULL CHECK (type IN ('STAFF','GOVERNMENT','OWNER','OTHER')),
    name                    varchar(100)  NOT NULL,
    mode                    varchar(10)   NOT NULL CHECK (mode IN ('PERCENT','AMOUNT')),
    rate                    numeric(5,2),
    max_rate                numeric(5,2),
    cashier_limit           numeric(5,2),
    approval_level          varchar(10)   NOT NULL CHECK (approval_level IN ('NONE','MANAGER','OWNER')),
    monthly_limit_per_staff numeric(12,2),
    active                  boolean       NOT NULL DEFAULT true,
    version                 int           NOT NULL DEFAULT 0,
    created_at              timestamptz   NOT NULL DEFAULT now(),
    updated_at              timestamptz   NOT NULL DEFAULT now(),
    created_by              uuid,
    updated_by              uuid
);

-- ---------------------------------------------------------------- Platform
-- Append-only (P1-AUD-02): the app role gets SELECT + INSERT only (see V3). Names are copied in at
-- write time so the log shows who did it even after a rename.
CREATE TABLE audit_log (
    id                 uuid PRIMARY KEY,
    branch_id          uuid         NOT NULL REFERENCES branch (id),
    at                 timestamptz  NOT NULL,
    user_id            uuid,
    username           varchar(32),
    user_full_name     varchar(100),
    terminal_id        uuid,
    terminal_name      varchar(50),
    action             varchar(30)  NOT NULL,
    entity_type        varchar(40)  NOT NULL,
    entity_id          varchar(100),
    before             jsonb,
    after              jsonb,
    approver_id        uuid,
    approver_username  varchar(32),
    approver_full_name varchar(100),
    reason             varchar(500),
    trace_id           varchar(64)
);
CREATE INDEX ix_audit_log_at ON audit_log (at);
CREATE INDEX ix_audit_log_entity ON audit_log (entity_type, entity_id);
CREATE INDEX ix_audit_log_user_at ON audit_log (user_id, at);

CREATE TABLE idempotency_record (
    id              uuid PRIMARY KEY,
    branch_id       uuid         NOT NULL REFERENCES branch (id),
    key             uuid         NOT NULL,
    endpoint        varchar(200) NOT NULL,
    user_id         uuid         NOT NULL,
    request_hash    varchar(64)  NOT NULL,
    response_status int          NOT NULL,
    response_body   jsonb,
    created_at      timestamptz  NOT NULL DEFAULT now(),
    UNIQUE (key, user_id, endpoint)
);
CREATE INDEX ix_idempotency_created ON idempotency_record (created_at);

CREATE TABLE notification (
    id         uuid PRIMARY KEY,
    branch_id  uuid          NOT NULL REFERENCES branch (id),
    user_id    uuid REFERENCES app_user (id),
    role_id    uuid REFERENCES role (id),
    type       varchar(30)   NOT NULL,
    title      varchar(120)  NOT NULL,
    body       varchar(1000) NOT NULL,
    read_at    timestamptz,
    created_at timestamptz   NOT NULL DEFAULT now(),
    CHECK (user_id IS NOT NULL OR role_id IS NOT NULL)
);
CREATE INDEX ix_notification_user_unread ON notification (user_id) WHERE read_at IS NULL;
